import{_ as a,o as t,c as l,a2 as s}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"L1 guide: the shell bridge","description":"","frontmatter":{},"headers":[],"relativePath":"l1/shell-bridge.md","filePath":"l1/shell-bridge.md"}'),o={name:"l1/shell-bridge.md"};function r(n,e,i,d,c,h){return t(),l("div",null,[...e[0]||(e[0]=[s(`<h1 id="l1-guide-the-shell-bridge" tabindex="-1">L1 guide: the shell bridge <a class="header-anchor" href="#l1-guide-the-shell-bridge" aria-label="Permalink to &quot;L1 guide: the shell bridge&quot;">​</a></h1><p>How module code becomes shell surface.</p><h2 id="registering-a-command-from-l1" tabindex="-1">Registering a command from L1 <a class="header-anchor" href="#registering-a-command-from-l1" aria-label="Permalink to &quot;Registering a command from L1&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>l1_ext_shell_register_command_ex(name, fn, help, wp_tag)</span></span></code></pre></div><p><code>fn</code> receives the argument string, returns 0/non-zero. The tag shows in <code>help -w</code>. The table holds 256 commands (233 registered today) - registration is refused with a clear error when full, never silently.</p><h2 id="enumerating-the-tui-pattern" tabindex="-1">Enumerating (the TUI pattern) <a class="header-anchor" href="#enumerating-the-tui-pattern" aria-label="Permalink to &quot;Enumerating (the TUI pattern)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>l1_ext_shell_list_commands_a_z()</span></span>
<span class="line"><span>l1_ext_shell_list_commands_by_wp()</span></span></code></pre></div><p>The TUI command bridge (<code>tui/tui_cmd.c</code>) enumerates the table through exactly these and renders the launcher - the reference consumer. Any L1 module may do the same.</p><h2 id="built-ins-and-jobs-l1-wp8cd-h" tabindex="-1">Built-ins and jobs (l1_wp8cd.h) <a class="header-anchor" href="#built-ins-and-jobs-l1-wp8cd-h" aria-label="Permalink to &quot;Built-ins and jobs (l1_wp8cd.h)&quot;">​</a></h2><p><code>shell_register_builtin</code> / <code>shell_unregister_builtin</code> (the self-test path uses these), <code>shell_run</code> (the interactive loop), <code>job_create / job_list / job_control</code> for background jobs, and <code>tool_register</code> to embed an ELF payload the shell can <code>run</code>.</p><h2 id="the-contract" tabindex="-1">The contract <a class="header-anchor" href="#the-contract" aria-label="Permalink to &quot;The contract&quot;">​</a></h2><ul><li>Names are ASCII, lowercase, dotted/multi-word allowed (<code>mkfs.fat32</code>, <code>health export</code> are real registrations).</li><li>Help is one line; argument errors print <code>usage: ...</code>.</li><li>Commands are never removed once shipped (<a href="./../root/CONTRIBUTING.html">CONTRIBUTING.md</a>).</li></ul>`,12)])])}const m=a(o,[["render",r]]);export{u as __pageData,m as default};
